  sql = `SELECT j.id::text AS id, j.list_key, j.list_label, j.template_key, j.subject, j.sender, j.delivery_mode, j.status, j.total_recipients, j.sent_count, j.failed_count, j.excluded_count, j.no_consent_count, j.started_at, j.completed_at, j.created_at, j.created_by, COUNT(r.id) FILTER (WHERE r.open_status = 'Opened') AS opened_count, COUNT(r.id) FILTER (WHERE r.open_status = 'Not Opened') AS not_opened_count, COUNT(r.id) FILTER (WHERE r.open_status = 'Not Tracked') AS not_tracked_count, COUNT(r.id) AS actual_recipient_count FROM public.member_list_mailout_jobs j LEFT JOIN public.member_list_mailout_recipients r ON r.job_id = j.id GROUP BY j.id ORDER BY j.created_at DESC`;
