    body += `<table><tr><th>Job ID</th><th>List</th><th>Subject</th><th>Sender</th><th>Mode</th><th>Status</th><th>Total</th><th>Sent</th><th>Excluded</th><th>No Consent</th><th>Opened</th><th>Not Opened</th><th>Created</th><th>Completed</th><th></th></tr>`;
    for (const j of rows) {
      const jResumeUrl = resumeBase + '?job_id=' + encodeURIComponent(j.id);
      const resumeCell = canResume(j.status) ? `<a class="btn btn-resume btn-sm" href="${jResumeUrl}">Resume</a>` : '';
      const deleteForm = `<form method="POST" action="${deleteUrl}" onsubmit="return confirm('Delete job ${escapeHtml(shortId(j.id))}? This cannot be undone.')" style="display:inline"><input type="hidden" name="job_id" value="${escapeHtml(j.id)}"><input type="hidden" name="return_url" value="${n8nBase}/webhook/member-list-mailout-report"><button class="btn btn-delete btn-sm" type="submit">Delete</button></form>`;
      body += `<tr><td><a href="?job_id=${encodeURIComponent(j.id)}">${escapeHtml(shortId(j.id))}</a></td><td>${escapeHtml(j.list_label||j.list_key||'')}</td><td title="${escapeHtml(j.subject||'')}">${escapeHtml(truncate(j.subject,35))}</td><td>${escapeHtml(j.sender||'')}</td><td>${escapeHtml(j.delivery_mode||'')}</td><td>${statusBadge(j.status)}</td><td>${escapeHtml(String(j.total_recipients??0))}</td><td>${escapeHtml(String(j.sent_count??0))}</td><td>${escapeHtml(String(j.excluded_count??0))}</td><td>${escapeHtml(String(j.no_consent_count??0))}</td><td>${escapeHtml(String(j.opened_count??0))}</td><td>${escapeHtml(String(j.not_opened_count??0))}</td><td>${escapeHtml(formatDt(j.created_at))}</td><td>${escapeHtml(formatDt(j.completed_at))}</td><td><div class="actions" style="margin:0;gap:6px">${resumeCell}${deleteForm}</div></td></tr>`;
    }
    body += `</table>`;
  } else {
    body += `<p class="empty">No mailout jobs found yet.</p>`;
  }
  body += `</div>`;
}
const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Member List Mailout Report</title>${baseStyle}</head><body>${body}</body></html>`;
return [{ json: { html } }];
